using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;
using TabulariusAI.Web.Data.Entities;
using TabulariusAI.Web.Data.Identity;

namespace TabulariusAI.Web.Data;

public sealed class TabulariusDbContext(DbContextOptions<TabulariusDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<AccountingEntity> AccountingEntities => Set<AccountingEntity>(); public DbSet<AnalysisDossier> AnalysisDossiers => Set<AnalysisDossier>(); public DbSet<SaftImport> SaftImports => Set<SaftImport>(); public DbSet<SaftAccount> SaftAccounts => Set<SaftAccount>(); public DbSet<SaftCustomer> SaftCustomers => Set<SaftCustomer>(); public DbSet<SaftSupplier> SaftSuppliers => Set<SaftSupplier>(); public DbSet<SaftProduct> SaftProducts => Set<SaftProduct>(); public DbSet<SaftTaxEntry> SaftTaxEntries => Set<SaftTaxEntry>(); public DbSet<SaftTransaction> SaftTransactions => Set<SaftTransaction>(); public DbSet<SaftTransactionLine> SaftTransactionLines => Set<SaftTransactionLine>(); public DbSet<SaftSalesInvoice> SaftSalesInvoices => Set<SaftSalesInvoice>(); public DbSet<SaftSalesInvoiceLine> SaftSalesInvoiceLines => Set<SaftSalesInvoiceLine>(); public DbSet<SaftStockMovement> SaftStockMovements => Set<SaftStockMovement>(); public DbSet<SaftStockMovementLine> SaftStockMovementLines => Set<SaftStockMovementLine>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        base.OnModelCreating(modelBuilder);
        modelBuilder.Entity<ApplicationUser>(entity => entity.Property(item => item.DisplayName).HasMaxLength(200).IsRequired());
        modelBuilder.Entity<AccountingEntity>(entity => { entity.Property(item => item.Name).HasMaxLength(200).IsRequired(); entity.Property(item => item.TaxRegistrationNumber).HasMaxLength(20).IsRequired(); entity.HasIndex(item => item.TaxRegistrationNumber).IsUnique(); });
        modelBuilder.Entity<AnalysisDossier>(entity => { entity.Property(item => item.Name).HasMaxLength(200).IsRequired(); entity.HasOne(item => item.AccountingEntity).WithMany(item => item.Dossiers).HasForeignKey(item => item.AccountingEntityId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(item => new { item.AccountingEntityId, item.FiscalYear }).IsUnique(); });
        modelBuilder.Entity<SaftImport>(entity => { entity.Property(item => item.OriginalFileName).HasMaxLength(260).IsRequired(); entity.Property(item => item.ContentHash).HasMaxLength(64).IsFixedLength(); entity.Property(item => item.SaftVersion).HasMaxLength(30).IsRequired(); entity.HasOne(item => item.Dossier).WithMany(item => item.Imports).HasForeignKey(item => item.DossierId).OnDelete(DeleteBehavior.Cascade); var index=entity.HasIndex(item=>item.ContentHash).IsUnique(); if(Database.IsSqlServer()) index.HasFilter("[ContentHash] IS NOT NULL"); });
        modelBuilder.Entity<SaftAccount>(entity => { entity.Property(item=>item.AccountId).HasMaxLength(100).IsRequired(); entity.Property(item=>item.Description).HasMaxLength(500).IsRequired(); entity.Property(item=>item.TaxonomyReference).HasMaxLength(100); entity.Property(item=>item.OpeningDebitBalance).HasPrecision(19,4); entity.Property(item=>item.OpeningCreditBalance).HasPrecision(19,4); entity.Property(item=>item.ClosingDebitBalance).HasPrecision(19,4); entity.Property(item=>item.ClosingCreditBalance).HasPrecision(19,4); entity.HasOne(item=>item.SaftImport).WithMany(item=>item.Accounts).HasForeignKey(item=>item.SaftImportId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(item=>new{item.SaftImportId,item.AccountId}).IsUnique(); });
        modelBuilder.Entity<SaftCustomer>(entity => { entity.Property(item=>item.CustomerId).HasMaxLength(100).IsRequired(); entity.Property(item=>item.AccountId).HasMaxLength(100).IsRequired(); entity.Property(item=>item.TaxId).HasMaxLength(30).IsRequired(); entity.Property(item=>item.CompanyName).HasMaxLength(300).IsRequired(); entity.HasOne(item=>item.SaftImport).WithMany(item=>item.Customers).HasForeignKey(item=>item.SaftImportId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(item=>new{item.SaftImportId,item.CustomerId}).IsUnique(); });
        modelBuilder.Entity<SaftSupplier>(entity => { entity.Property(item=>item.SupplierId).HasMaxLength(100).IsRequired(); entity.Property(item=>item.AccountId).HasMaxLength(100).IsRequired(); entity.Property(item=>item.TaxId).HasMaxLength(30).IsRequired(); entity.Property(item=>item.CompanyName).HasMaxLength(300).IsRequired(); entity.HasOne(item=>item.SaftImport).WithMany(item=>item.Suppliers).HasForeignKey(item=>item.SaftImportId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(item=>new{item.SaftImportId,item.SupplierId}).IsUnique(); });
        modelBuilder.Entity<SaftProduct>(entity => { entity.Property(item=>item.ProductType).HasMaxLength(10).IsRequired(); entity.Property(item=>item.ProductCode).HasMaxLength(100).IsRequired(); entity.Property(item=>item.ProductGroup).HasMaxLength(100); entity.Property(item=>item.ProductDescription).HasMaxLength(500).IsRequired(); entity.Property(item=>item.ProductNumberCode).HasMaxLength(100).IsRequired(); entity.HasOne(item=>item.SaftImport).WithMany(item=>item.Products).HasForeignKey(item=>item.SaftImportId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(item=>new{item.SaftImportId,item.ProductCode}).IsUnique(); });
        modelBuilder.Entity<SaftTaxEntry>(entity => { entity.Property(item=>item.TaxType).HasMaxLength(20).IsRequired(); entity.Property(item=>item.TaxCountryRegion).HasMaxLength(10).IsRequired(); entity.Property(item=>item.TaxCode).HasMaxLength(20).IsRequired(); entity.Property(item=>item.Description).HasMaxLength(500).IsRequired(); entity.Property(item=>item.TaxPercentage).HasPrecision(9,4); entity.Property(item=>item.TaxAmount).HasPrecision(19,4); entity.HasOne(item=>item.SaftImport).WithMany(item=>item.TaxEntries).HasForeignKey(item=>item.SaftImportId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(item=>item.SaftImportId); entity.HasIndex(item=>new{item.SaftImportId,item.TaxType,item.TaxCountryRegion,item.TaxCode}); });
        modelBuilder.Entity<SaftTransaction>(entity => { entity.Property(item=>item.JournalId).HasMaxLength(100).IsRequired(); entity.Property(item=>item.JournalDescription).HasMaxLength(500).IsRequired(); entity.Property(item=>item.TransactionId).HasMaxLength(100).IsRequired(); entity.Property(item=>item.SourceId).HasMaxLength(100).IsRequired(); entity.Property(item=>item.Description).HasMaxLength(500).IsRequired(); entity.Property(item=>item.DocArchivalNumber).HasMaxLength(100); entity.Property(item=>item.TransactionType).HasMaxLength(10).IsRequired(); entity.Property(item=>item.CustomerId).HasMaxLength(100); entity.Property(item=>item.SupplierId).HasMaxLength(100); entity.HasOne(item=>item.SaftImport).WithMany(item=>item.Transactions).HasForeignKey(item=>item.SaftImportId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(item=>new{item.SaftImportId,item.TransactionId}).IsUnique(); entity.HasIndex(item=>new{item.SaftImportId,item.TransactionDate}); entity.HasIndex(item=>new{item.SaftImportId,item.JournalId}); });
        modelBuilder.Entity<SaftTransactionLine>(entity => { entity.Property(item=>item.RecordId).HasMaxLength(100).IsRequired(); entity.Property(item=>item.AccountId).HasMaxLength(100).IsRequired(); entity.Property(item=>item.SourceDocumentId).HasMaxLength(100); entity.Property(item=>item.Description).HasMaxLength(500).IsRequired(); entity.Property(item=>item.Side).HasMaxLength(1).IsFixedLength().IsRequired(); entity.Property(item=>item.Amount).HasPrecision(19,4); entity.HasOne(item=>item.SaftTransaction).WithMany(item=>item.Lines).HasForeignKey(item=>item.SaftTransactionId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(item=>new{item.SaftTransactionId,item.RecordId}).IsUnique(); entity.HasIndex(item=>item.AccountId); });
        modelBuilder.Entity<SaftSalesInvoice>(entity => { entity.Property(item=>item.InvoiceNo).HasMaxLength(100).IsRequired(); entity.Property(item=>item.InvoiceStatus).HasMaxLength(10).IsRequired(); entity.Property(item=>item.InvoiceType).HasMaxLength(10).IsRequired(); entity.Property(item=>item.SourceId).HasMaxLength(100).IsRequired(); entity.Property(item=>item.CustomerId).HasMaxLength(100); entity.Property(item=>item.TaxPayable).HasPrecision(19,4); entity.Property(item=>item.NetTotal).HasPrecision(19,4); entity.Property(item=>item.GrossTotal).HasPrecision(19,4); entity.HasOne(item=>item.SaftImport).WithMany(item=>item.SalesInvoices).HasForeignKey(item=>item.SaftImportId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(item=>new{item.SaftImportId,item.InvoiceNo}).IsUnique(); entity.HasIndex(item=>new{item.SaftImportId,item.InvoiceDate}); });
        modelBuilder.Entity<SaftSalesInvoiceLine>(entity => { entity.Property(item=>item.LineNumber).HasMaxLength(100).IsRequired(); entity.Property(item=>item.ProductCode).HasMaxLength(100).IsRequired(); entity.Property(item=>item.ProductDescription).HasMaxLength(500).IsRequired(); entity.Property(item=>item.Quantity).HasPrecision(19,4); entity.Property(item=>item.UnitOfMeasure).HasMaxLength(50).IsRequired(); entity.Property(item=>item.UnitPrice).HasPrecision(19,4); entity.Property(item=>item.TaxType).HasMaxLength(20); entity.Property(item=>item.TaxCode).HasMaxLength(20); entity.Property(item=>item.TaxPercentage).HasPrecision(9,4); entity.Property(item=>item.DebitAmount).HasPrecision(19,4); entity.Property(item=>item.CreditAmount).HasPrecision(19,4); entity.HasOne(item=>item.SaftSalesInvoice).WithMany(item=>item.Lines).HasForeignKey(item=>item.SaftSalesInvoiceId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(item=>new{item.SaftSalesInvoiceId,item.LineNumber}).IsUnique(); entity.Ignore(item=>item.LineAmount); });
        modelBuilder.Entity<SaftStockMovement>(entity => { entity.Property(item=>item.DocumentNumber).HasMaxLength(100).IsRequired(); entity.Property(item=>item.DocumentStatus).HasMaxLength(10).IsRequired(); entity.Property(item=>item.MovementType).HasMaxLength(10).IsRequired(); entity.Property(item=>item.SourceId).HasMaxLength(100).IsRequired(); entity.Property(item=>item.CustomerId).HasMaxLength(100); entity.Property(item=>item.SupplierId).HasMaxLength(100); entity.HasOne(item=>item.SaftImport).WithMany(item=>item.StockMovements).HasForeignKey(item=>item.SaftImportId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(item=>new{item.SaftImportId,item.DocumentNumber}).IsUnique(); entity.HasIndex(item=>new{item.SaftImportId,item.MovementDate}); });
        modelBuilder.Entity<SaftStockMovementLine>(entity => { entity.Property(item=>item.LineNumber).HasMaxLength(100).IsRequired(); entity.Property(item=>item.ProductCode).HasMaxLength(100).IsRequired(); entity.Property(item=>item.ProductDescription).HasMaxLength(500).IsRequired(); entity.Property(item=>item.Quantity).HasPrecision(19,4); entity.Property(item=>item.UnitOfMeasure).HasMaxLength(50).IsRequired(); entity.Property(item=>item.UnitPrice).HasPrecision(19,4); entity.HasOne(item=>item.SaftStockMovement).WithMany(item=>item.Lines).HasForeignKey(item=>item.SaftStockMovementId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(item=>new{item.SaftStockMovementId,item.LineNumber}).IsUnique(); });
    }
}
